import sys

def calc(expr: str) -> int | str:
    sys.setrecursionlimit(max(sys.getrecursionlimit(), 10000))
    tokens = []
    i, n = 0, len(expr)
    while i < n:
        c = expr[i]
        if c == ' ':
            i += 1
        elif c.isdigit():
            j = i
            while j < n and expr[j].isdigit():
                j += 1
            tokens.append(int(expr[i:j]))
            i = j
        else:
            tokens.append(c)
            i += 1

    class Err(Exception):
        pass

    pos = 0

    def peek():
        return tokens[pos] if pos < len(tokens) else None

    def tdiv(a, b):
        if b == 0:
            raise Err()
        q = abs(a) // abs(b)
        if (a < 0) != (b < 0):
            q = -q
        return q

    def power(a, b):
        if b < 0:
            raise Err()
        return a ** b

    def primary():
        nonlocal pos
        t = tokens[pos]
        if t == '(':
            pos += 1
            v = expression()
            pos += 1  # ')'
            return v
        pos += 1
        return t

    def count_minus():
        nonlocal pos
        k = 0
        while peek() == '-':
            k += 1
            pos += 1
        return k

    def unary():
        nonlocal pos
        k = count_minus()
        # power chain: p0 ^ (-k1) p1 ^ (-k2) p2 ...
        prims = [primary()]
        signs = []
        while peek() == '^':
            pos += 1
            signs.append(count_minus())
            prims.append(primary())
        v = prims[-1]
        for idx in range(len(prims) - 2, -1, -1):
            if signs[idx] % 2:
                v = -v
            v = power(prims[idx], v)
        if k % 2:
            v = -v
        return v

    def term():
        nonlocal pos
        v = unary()
        while True:
            t = peek()
            if t == '*':
                pos += 1
                v = v * unary()
            elif t == '/':
                pos += 1
                v = tdiv(v, unary())
            elif t == '%':
                pos += 1
                b = unary()
                q = tdiv(v, b)
                v = v - b * q
            else:
                return v

    def expression():
        nonlocal pos
        v = term()
        while True:
            t = peek()
            if t == '+':
                pos += 1
                v = v + term()
            elif t == '-':
                pos += 1
                v = v - term()
            else:
                return v

    try:
        return expression()
    except Err:
        return "error"
